.sl-category-story.sl-bg-main { background-color: var(--smartlearn-bg); }
.sl-category-story .sl-story-badge { background-color: var(--smartlearn-bg); }
.sl-category-story .sl-text-primary { color: var(--smartlearn-primary); }
.sl-category-story .sl-text-emphasis { color: var(--smartlearn-text); }
.sl-category-story .sl-text-muted { color: var(--smartlearn-text-muted); }
.sl-category-story .sl-bg-card { background-color: var(--smartlearn-card-bg); border: 1px solid var(--smartlearn-card-border); }
.sl-category-story .sl-border { border-color: var(--smartlearn-card-border); }
.sl-category-story .sl-card-radius { border-radius: var(--smartlearn-radius, 1rem); }
.sl-category-story h2, .sl-category-story h3 { font-family: var(--smartlearn-heading-font, inherit); }
.sl-category-story .sl-sticky-col { top: calc(var(--smartlearn-navbar-height, 70px) + 1.5rem); }
.sl-category-story .sl-media-fallback { background-color: var(--smartlearn-card-bg); }
.sl-category-story .sl-story-item { transition: background-color 0.25s ease, border-color 0.25s ease, box-shadow 0.25s ease; }
.sl-category-story .sl-story-inactive { background-color: transparent; border-color: transparent; }
.sl-category-story .sl-story-inactive .sl-story-title,
.sl-category-story .sl-story-inactive .sl-story-badge { opacity: 0.72; transition: opacity 0.2s ease; }
.sl-category-story .sl-story-item.is-active .sl-story-title,
.sl-category-story .sl-story-item.is-active .sl-story-badge { opacity: 1; }
.sl-category-story .sl-story-item.is-collapsed .sl-story-panel { display: none; }
.sl-category-story .sl-badge-subtle {
    background-color: var(--smartlearn-card-bg);
    background-color: color-mix(in oklab, var(--smartlearn-primary) 14%, var(--smartlearn-card-bg));
    color: var(--smartlearn-primary);
    border: 1px solid var(--smartlearn-card-border);
    border: 1px solid color-mix(in oklab, var(--smartlearn-primary) 28%, var(--smartlearn-card-border));
}
.sl-category-story .sl-btn-primary {
    background-color: var(--smartlearn-btn-bg);
    color: var(--smartlearn-btn-text);
    border: 1px solid var(--smartlearn-btn-bg);
    transition: background-color 0.2s ease, border-color 0.2s ease;
}
.sl-category-story .sl-btn-primary:hover,
.sl-category-story .sl-btn-primary:focus-visible {
    background-color: var(--smartlearn-btn-hover-bg);
    border-color: var(--smartlearn-btn-hover-bg);
    color: var(--smartlearn-btn-text);
}
.sl-category-story .sl-focus-ring:focus-visible {
    outline: 3px solid var(--smartlearn-primary);
    outline-offset: 3px;
}
.sl-category-story .sl-fade-transition { transition: opacity 0.3s ease; }
@media (prefers-reduced-motion: reduce) {
    .sl-category-story .sl-story-item, .sl-category-story .sl-fade-transition, .sl-category-story .sl-btn-primary { transition: none; }
}
@media (min-width: 992px) {
    .sl-category-story { padding-top: 6rem !important; padding-bottom: 6rem !important; }
}

