(function() {
    const init = () => {
        document.querySelectorAll('.sl-category-story').forEach((section) => {
            if (section.dataset.slInit === '1') return;
            section.dataset.slInit = '1';

            const items = Array.from(section.querySelectorAll('.sl-story-item'));
            const previewImg = section.querySelector('.sl-story-preview-img');
            if (!items.length) return;

            let fadeTimer = null;

            const setActive = (target) => {
                items.forEach((item) => {
                    const active = item === target;
                    const trigger = item.querySelector('.sl-story-trigger');
                    const badge = item.querySelector('.sl-story-badge');
                    item.classList.toggle('is-active', active);
                    item.classList.toggle('sl-bg-card', active);
                    item.classList.toggle('sl-border', active);
                    item.classList.toggle('sl-story-inactive', !active);
                    item.classList.toggle('is-collapsed', !active);
                    if (trigger) trigger.setAttribute('aria-expanded', active ? 'true' : 'false');
                    if (badge) {
                        badge.classList.toggle('sl-badge-subtle', active);
                        badge.classList.toggle('sl-bg-main', !active);
                        badge.classList.toggle('sl-border', !active);
                        badge.classList.toggle('sl-text-muted', !active);
                    }
                });

                const srcImg = target.querySelector('.sl-story-src-img');
                const newSrc = srcImg ? srcImg.getAttribute('src') : '';
                const newAlt = srcImg ? (srcImg.getAttribute('alt') || '') : '';
                if (previewImg && newSrc && previewImg.getAttribute('src') !== newSrc) {
                    if (fadeTimer) clearTimeout(fadeTimer);
                    const reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
                    if (reduced) {
                        previewImg.setAttribute('src', newSrc);
                        previewImg.setAttribute('alt', newAlt);
                        previewImg.style.opacity = '1';
                        return;
                    }
                    previewImg.style.opacity = '0.4';
                    fadeTimer = setTimeout(() => {
                        previewImg.onload = () => { previewImg.style.opacity = '1'; };
                        previewImg.onerror = () => { previewImg.style.opacity = '1'; };
                        previewImg.setAttribute('src', newSrc);
                        previewImg.setAttribute('alt', newAlt);
                        if (previewImg.complete) previewImg.style.opacity = '1';
                    }, 160);
                }
            };

            setActive(items[0]);

            items.forEach((item) => {
                const trigger = item.querySelector('.sl-story-trigger');
                if (trigger) {
                    trigger.addEventListener('click', () => setActive(item));
                }
                item.addEventListener('mouseenter', () => {
                    if (window.matchMedia('(min-width: 992px)').matches) {
                        setActive(item);
                    }
                });
            });
        });
    };
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', init);
    } else {
        init();
    }
})();
